import React, { useState, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import NavBar from '../Components/NavBar'
import Footer from '../Components/Footer'
import './advertisements.css'

const posters = [
  { 
    id: 1, 
    title: 'T-shirt Design Course', 
    imageUrl: '/Images/home1.jpeg', 
    // UPDATED DESCRIPTION
    description: `පහත කරුණු ආවරණය කෙරේ:\n
    මුල සිට සරලවම T-shirt පතොරම් සකස් කරගන්නා ආකාරය කියාදීම
* අවශ්‍යකරන පතොරම් ලබාදීම
* සමාජ මාධ්‍ය හරහා අලෙවි කරන ආකාරය
* AI භාවිතය මගින් පින්තූර සැකසීම
* ඩිජිටල් අලෙවිකරණය
* Screen printing
* DTF printing
* මිල ගණනය කිරීම 
* Size chart
* Face book ඇඩ් boost කිරීම`, 
    tag: 'Beginner Friendly' 
  },
  { id: 2, title: 'Batik Techniques', imageUrl: '/Images/home2.jpeg', description: 'Explore traditional and modern Batik methods...', tag: 'Intermediate' },
  { id: 3, title: 'Screen Printing Workshop', imageUrl: '/Images/home2.jpeg', description: 'Hands-on training for multi-color screen printing...', tag: 'Workshop' }
]

const courseOptions = [
  { name: 'T-Shirt Course', price: 1500, key: 'courseTshirt' },
  { name: 'Batik Course', price: 2000, key: 'courseBatik' },
  { name: 'Screen Printing Course', price: 2500, key: 'courseScreen' },
]

const itemOptions = [
  { name: 'Pattern Making Book', price: 500, key: 'itemBook' },
  { name: 'Video Course', price: 1000, key: 'itemVideo' },
  { name: 'T-shirt 3 Pattern Set', price: 800, key: 'itemPatternSet' },
  { name: 'Starter Ink Kit', price: 700, key: 'itemInkKit' },
]

// Target WhatsApp Number
const WHATSAPP_NUMBER = '94743035311'; // Note: Must include country code (94) without '+'

export default function Advertisements() {
  const navigate = useNavigate() // Keep navigate for potential future use, but don't use it now

  // --- Form State Management ---
  const [participateChecked, setParticipateChecked] = useState(false)
  const [selections, setSelections] = useState({
    courseTshirt: false,
    courseBatik: false,
    courseScreen: false,
    itemBook: false,
    itemVideo: false,
    itemPatternSet: false,
    itemInkKit: false,
  })
  const [userDetails, setUserDetails] = useState({
    name: '',
    email: '',
    phone: ''
  })

  // Removed goToDetail function

  const handleSelectionChange = (key) => {
    setSelections(prev => ({
      ...prev,
      [key]: !prev[key]
    }))
  }

  const handleUserDetailChange = (e) => {
    setUserDetails(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }))
  }
  
  // --- Calculation Logic (Memoized for performance) ---
  const calculatedTotal = useMemo(() => {
    let total = 0
    // Sum courses
    courseOptions.forEach(option => {
      if (selections[option.key]) {
        total += option.price
      }
    })
    // Sum items
    itemOptions.forEach(option => {
      if (selections[option.key]) {
        total += option.price
      }
    })
    return total
  }, [selections])

  // --- WhatsApp URL Generator ---
  const generateWhatsAppUrl = (total) => {
    // 1. Get Selected Items
    const selectedCourses = courseOptions
      .filter(option => selections[option.key])
      .map(option => `\t- ${option.name} (LKR ${option.price})`).join('\n');

    const selectedItems = itemOptions
      .filter(option => selections[option.key])
      .map(option => `\t- ${option.name} (LKR ${option.price})`).join('\n');

    // 2. Format the Message Body
    let messageBody = `
*NEW COURSE REGISTRATION*\n
*Personal Details:*\n
\tName: ${userDetails.name}
\tEmail: ${userDetails.email}
\tPhone: ${userDetails.phone}
\n
*Selected Courses:*
${selectedCourses || '\t(No courses selected)'}
\n
*Selected Items:*
